import{z as s,x as d,o as t,c as p,q as o,j as B,D as e,d as n,s as l,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"消耗战","description":"","frontmatter":{"title":"消耗战","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/war-of-attrition.md","filePath":"econ/war-of-attrition.md","lastUpdated":1791063341000}'),A={name:"econ/war-of-attrition.md"};function c(m,a,C,h,f,u){const i=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="消耗战" tabindex="-1">消耗战 <a class="header-anchor" href="#消耗战" aria-label="Permalink to &quot;消耗战&quot;">​</a></h1><div class="epigraph"><p>冲突的代价落在时间上：先撤者失去奖赏，双方都为已耗掉的等待付钱；均衡是混合的放弃时间，而不是某一方纯策略硬撑。</p><footer>—— Maynard Smith, The Theory of Games and the Evolution of Animal Conflicts, Journal of Theoretical Biology, 1974；Bishop and Cannings, Advances in Applied Probability, 1978</footer></div><p><a href="/econ/cheap-talk">上一课</a>的消息不进支付。缺口是许多僵局里「不说话、不让步」本身在烧资源：两家抢市场、两只动物争领地、公共品等谁先贡献。等待有成本，奖赏只给撑到最后的那一个。本课钉消耗战的混合均衡，不把廉价分区再推一遍，也不把不完全信息估值写成下一课的贝叶斯纳什。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两人，奖赏价值 \\(v\\)，单位时间成本 \\(c\\)。每人选放弃时刻 \\(t_i\\ge 0\\)。较小的 \\(t\\) 先走，先走者得 \\(0\\) 并已付 \\(c t\\)；胜者得 \\(v\\) 并付同样的等待成本。平局可均分或再随机，教具里零测。</p><p>纯策略纳什对不上：若对方一定撑到 \\(T\\)，自己的最优是要么立刻走（若 \\(cT\\gt v\\)），要么刚好比 \\(T\\) 晚一点。双方都「刚好比对方晚」不可行。故均衡必须混合：放弃时间有连续分布，使对手在每一瞬间无差异于「再等 \\(dt\\)」与「现在走」。</p><p><span class="marginnote">数字实例：\\(v=100\\) 万、每小时 \\(c=1\\) 万，均衡风险率 \\(\\lambda=c/v=1\\%\\) 每小时。僵持的期望时长是 \\(1/(2\\lambda)=50\\) 小时，双方各期望烧掉约 50 万——加总恰好等于 100 万的奖赏，租金全部耗散在等待里。</span></p><h3 id="不是轮流出价的贴现饼" tabindex="-1">不是轮流出价的贴现饼 <a class="header-anchor" href="#不是轮流出价的贴现饼" aria-label="Permalink to &quot;不是轮流出价的贴现饼&quot;">​</a></h3><p>Rubinstein 里拖延伤害双方，但提议一被接受就交割，SPE 是纯策略分割。消耗战没有「接受即结束」的要约，只有「谁先眨眼」。延迟的成本是沉没的时间，不是把饼贴现后仍按协议切。廉价交谈则连这点沉没成本都没有。</p><p><span class="marginnote">演化稳定策略（ESS）是 Maynard Smith 的原语言：种群里「硬撑」与「早退」的混合比例，使两种行为期望支付相等。经济翻译成纳什混合；Bishop–Cannings 给出一般支付下的分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：完全信息、对称、连续时间、线性等待成本。先写无差异：若对手的放弃有风险率 \\(\\lambda\\)，再等 \\(dt\\) 的期望收益为 \\(-c\\,dt+\\lambda dt\\cdot v\\)。令其等于立刻放弃的 \\(0\\)，得 \\(\\lambda=c/v\\)。指数分布 \\(F(t)=1-e^{-(c/v)t}\\) 是对称混合均衡。非对称 \\(v_i\\) 时，弱者（估值低或成本高）的风险率更高，更可能先走。</p>',12)),(t(),B(r,null,{default:e(()=>[l(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CT%5B%22%E5%BB%89%E4%BB%B7%E4%BA%A4%E8%B0%88%EF%BC%9A%E5%BC%80%E5%8F%A3%E6%97%A0%E6%88%90%E6%9C%AC%22%5D%20--%3E%20WA%5B%22%E6%B6%88%E8%80%97%E6%88%98%EF%BC%9A%E7%AD%89%E5%BE%85%E7%83%A7%E9%92%B1%22%5D%0A%20%20WA%20--%3E%20MIX%5B%22%E6%97%A0%E7%BA%AF%E7%AD%96%E7%95%A5%E7%BA%B3%E4%BB%80%22%5D%0A%20%20MIX%20--%3E%20HAZ%5B%22%E9%A3%8E%E9%99%A9%E7%8E%87%E4%BD%BF%E5%AF%B9%E6%89%8B%E6%97%A0%E5%B7%AE%E5%BC%82%22%5D%0A%20%20HAZ%20--%3E%20EXIT%5B%22%E5%85%88%E8%B5%B0%E8%80%85%E8%BE%93%EF%BC%8C%E5%8F%8C%E6%96%B9%E9%83%BD%E4%BB%98%E5%B7%B2%E8%80%97%E6%97%B6%E9%97%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"风险率 \\(\\lambda=c/v\\) 把「再等一秒」钉成公平赌博：成本 \\(c\\) 对上「对方刚好放弃」的概率。\\(v\\) 越大或 \\(c\\) 越小，撑得越久，结束越晚。",-1)),a[4]||(a[4]=E("p",null,"支付结构像全支付：输家也付了等待，赢家额外得到 \\(v\\)。后课拍卖里会把这句话写成叫价；本课先停在时间。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"无差异条件把「再撑一秒」的边际成本钉在「对方刚好在这一秒放弃」的概率上。均衡里没有人严格想硬撑到无穷——那会使对手早走、自己白烧。也没有人严格想立刻走——因为对方也在混合，立刻走丢掉了免费赢的机会。期望支付常被压到「一开始就放弃」的水平：租金在等待里耗尽。这是完全信息下的消耗，不是私型。",-1)),(t(),B(r,null,{default:e(()=>[l(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEC%5B%22%E5%86%8D%E6%92%91%E4%B8%80%E7%A7%92%22%5D%20--%3E%20COST%5B%22%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%EF%BC%9A%E7%83%A7%E6%8E%89%20c%C2%B7dt%22%5D%0A%20%20SEC%20--%3E%20CHANCE%5B%22%E6%9C%BA%E4%BC%9A%EF%BC%9A%E5%AF%B9%E6%96%B9%E6%81%B0%E5%A5%BD%E6%AD%A4%E5%88%BB%E6%94%BE%E5%BC%83%EF%BC%8C%E6%A6%82%E7%8E%87%20%CE%BB%C2%B7dt%22%5D%0A%20%20CHANCE%20--%3E%20WIN%5B%22%E8%B5%A2%E5%BE%97%20v%22%5D%0A%20%20COST%20--%3E%20IND%7B%22%E4%B8%A4%E8%80%85%E6%9C%9F%E6%9C%9B%E7%9B%B8%E6%8A%B5%22%7D%0A%20%20WIN%20--%3E%20IND%0A%20%20IND%20--%3E%20ZERO%5B%22%CE%BB%C2%B7v%20%3D%20c%20%E2%87%92%20%E9%A3%8E%E9%99%A9%E7%8E%87%20%CE%BB%20%3D%20c%2Fv%22%5D%0A%20%20ZERO%20--%3E%20MIX%5B%22%E5%AF%B9%E7%A7%B0%E5%9D%87%E8%A1%A1%EF%BC%9A%E6%8C%87%E6%95%B0%E5%88%86%E5%B8%83%E7%9A%84%E6%94%BE%E5%BC%83%E6%97%B6%E5%88%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">直觉类比：\\(\\lambda=c/v\\) 把「再撑一秒」变成一张小彩票——花 \\(c\\) 元买一个极小的中奖概率（对方恰好这一秒走人），赔率恰好公平。于是你既舍不得立刻走（彩票可能是白捡的赢），也不敢多买（每秒都得付钱），两头都不占优，这才叫均衡。</span></p><p>与无名氏的对照：重复博弈用未来路径惩罚；消耗战是一次性时序，惩罚已经写进瞬时成本，不需要下一阶段改玩法。与进入遏制也不同：那里威胁要在子博弈里可信；这里「继续等」在每一时刻都是混合里的最优反应之一。</p><p>期望支付被压到立刻放弃的水平，是完全耗散：奖赏的社会价值在等待里烧光（若等待本身无产出）。这与全支付对称混合同一会计，只是把 \\(x\\) 叫成时间。人数增加时，每人的风险率上升，结束更快，但总等待成本仍可把 \\(v\\) 耗尽——「更多竞争」不必留下租金。</p><h3 id="生物学与市场退出是同一方程" tabindex="-1">生物学与市场退出是同一方程 <a class="header-anchor" href="#生物学与市场退出是同一方程" aria-label="Permalink to &quot;生物学与市场退出是同一方程&quot;">​</a></h3><p>两只动物按体型比拼展示，展示消耗能量；两家产能过剩，谁先关厂谁认亏。风险率语言可直接搬。非对称时，表面上「强者应立刻赢」，混合均衡里强者仍以正概率早走——否则弱者不会愿意跟，无差异会坏。</p><p><span class="marginnote">常见误区：初学者容易以为「强者会立刻获胜，弱者马上认输」。实际上混合均衡里强者也以正概率早早放弃——若他从不早走，弱者的最优就是立刻认输，弱者一认输强者又何必硬撑，无差异整条崩坏。混合的意义正在于让对方猜不透。</span></p><p><span class="marginnote">不完全信息消耗战（Hendricks–Weiss–Wilson 一类）把 \\(v\\) 换成私型，放弃时间变成类型的增函数，效率损失是「拖得太久」。那是 BNE；本课完全信息已经需要混合，不要把两层叠成一句「都是消耗」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多人、奖赏可分、等待成本凸，风险率公式要改。拍卖时钟、专利竞赛有时同构于全支付，后课再写支付规则。也不要把消耗战写成限价簿里挂单等待成交——本栏没有队列。</p><p>公共品「等别人先贡献」是同一风险率：每人希望对方先眨眼（先提供），均衡延迟，供给不足。与自愿贡献的纳什数量不足是表亲，这里不足写在时间上。私型一进来，放弃时间变成类型的揭示，接到贝叶斯纳什。</p><p>后课默认：完全信息消耗战的对称均衡是指数放弃，租金耗在时间上。下一课进入类型未知：贝叶斯纳什把私型写进策略，不再默认支付公开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>廉价交谈不烧资源；消耗战的等待本身就是支付。</li><li>纯策略撑不住，对称均衡是使对手无差异的风险率 \\(c/v\\)。</li><li>双方都付已耗时间，结构上接近全支付。</li><li>完全信息已要混合；私型消耗是后课 BNE。</li><li>出处：Maynard Smith, <em>JTB</em>, 1974；Bishop and Cannings, 1978。</li></ul>',13))])}const T=s(A,[["render",c]]);export{b as __pageData,T as default};
